rows.P4-3 adaptor over any sequence, closure:
struct Done {};
struct Count { int n;
  struct It { int i, n; constexpr int operator*() const { return i; }
    constexpr It& operator++() { ++i; return *this; }
    constexpr bool operator==(Done) const { return i == n; } };
  constexpr It begin() const { return {0, n}; }
  constexpr Done end() const { return {}; } };
template <class S, class F> struct Filtered { S base; F keep;
  using BaseIt = decltype(static_cast<const S*>(nullptr)->begin());
  using BaseEnd = decltype(static_cast<const S*>(nullptr)->end());
  struct It { BaseIt it; BaseEnd end; F keep;
    constexpr void skip() { while (!(it == end) && !keep(*it)) ++it; }
    constexpr auto operator*() const { return *it; }
    constexpr It& operator++() { ++it; skip(); return *this; }
    constexpr bool operator==(Done) const { return it == end; } };
  constexpr It begin() const { It i{base.begin(), base.end(), keep}; i.skip(); return i; }
  constexpr Done end() const { return {}; } };
constexpr int f() { int s = 0; auto even = [](int v) { return v % 2 == 0; };
  for (int v : Filtered{Count{7}, even}) s += v; return s; }
static_assert(f() == 12);

